import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem90 nao escolhe edicao PS5 por conflito nem altera operacao',()=>{const p={id:'Kyw9WRrxRLj36DL50JfQ',titulo:'Console PlayStation 5 Slim Disk 1 TB — Astro Bot e Gran Turismo 7',preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.match(x.comentario,/divergência/);assert.match(x.comentario,/CFI 2114B/);assert.doesNotMatch(x.titulo,/Disk|1 TB|Digital|Astro Bot/i);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');});
